# Simple image augmentation (conceptual)
def augment(image, operations):
    for op in operations:
        if op == "flip":
            image = list(reversed(image))
        elif op == "shift":
            image = [image[-1]] + image[:-1]
    return image

img = [1, 2, 3, 4, 5]
print("original:", img)
print("flipped: ", augment(img, ["flip"]))
print("shifted: ", augment(img, ["shift"]))
